// AUTO-GENERATED by tools/director.py — do not hand-edit.
// blocking.js — one place that knows how a character acts, so no shot invents its own version.
import { V, ease, prog, clamp, lerp, wordTime, talkAmount } from '/engine/core.js';
import { drawFigure } from '/engine/rig2d.js';
import { drawInkBean } from '/chars/inkbean.js';
import { PRESETS, mixFaces } from '/chars/acting.js';
import { CAST } from './cast.js';

// character rig: 'stick' = rig2d stick figures, 'inkbean' = the hand-drawn ink-bean rig
export const INKBEAN = true;

export const outfitOf = (who) => CAST[who] || Object.values(CAST)[0] || {};

export function person(g, who, o) {
  const outfit = o.outfit || outfitOf(who);
  return INKBEAN ? drawInkBean(g, { ...o, outfit }) : drawFigure(g, { ...o, outfit });
}

// Continuous expression: two presets blended across a window, never a hard cut.
// rig2d faces are discrete presets; the ink-bean rig takes continuous values.
export function faceAt(t, at, a, b, w = 0.22) {
  const A = PRESETS[a] || PRESETS.neutral;
  if (!b || at == null) return { ...A, look: (A.look || [0, 0]).slice() };
  const B = PRESETS[b] || A;
  return mixFaces(A, B, ease.inOut(prog(t, at - w, at + w)));
}

// Mouth amount for a line occupying [from,to] in SHOT-local time.
// talkAmount is keyed on GLOBAL time, so passing shot-local numbers straight
// through would silently mute every shot after the first.
export function speak(info, t, from = 0.05, to = 1e9) {
  const g0 = info.globalT - t;
  return talkAmount(info.globalT, g0 + from, g0 + to);
}

// A blink is 0.10 s. Blinking exactly on an expression change hides the jump
// between two discrete face presets — the oldest trick in 2D animation.
export const BLINK = 0.10;
export function blinkAt(t, at, mid) {
  if (at != null && Math.abs(t - at) < BLINK * 0.5) return 1;
  if (mid != null && Math.abs(t - mid) < BLINK * 0.5) return 1;
  return 0;
}

// Discrete expression presets, switched on a blink. Returns `a` before `at`.
export function exprAt(t, at, a, b) {
  if (!b || at == null) return a;
  return t >= at ? b : a;
}

// Vertical: a 1080x1920 frame has 78% more height than 1920x1080, so landscape
// scales make a head unreadably small on a phone. These restore it.
export const S_WIDE = () => V(1.45, 2.20);
export const S_MED = () => V(1.75, 2.70);
export const S_CLOSE = () => V(2.6, 3.15);
